 s=f'<?xml version="1.0" encoding="utf-8"?><feed xmlns="http://www.w3.org/2005/Atom" xml:lang="{LANG}"><title>{t("Марк Сердюк – обновления","Mark Serdyuk – updates")}</title><id>{DOMAIN}{home()}feed.xml</id><link href="{DOMAIN}{home()}feed.xml" rel="self"/><link href="{DOMAIN}{home()}"/><updated>2026-11-19T00:00:00Z</updated><author><name>{t("Марк Сердюк","Mark Serdyuk")}</name></author>'
 for id,title,summary in entries:s+=f'<entry><id>{DOMAIN}/milestones/{id}</id><title>{title}</title><link href="{DOMAIN}{home()}#work"/><updated>2026-11-19T00:00:00Z</updated><summary>{summary}</summary></entry>'
